 *
 * @return True if engine is busy, false otherwise
 */
[[nodiscard]] bool IsBusy() const noexcept
{
    return triggerDepth > 0 || reloading.load(std::memory_order_acquire);
}

/**
 * @brief Checks if engine is enabled (with acquire semantics)
