bool HasCallbacks(HookInfo hook, uint32 entryId) const
{
    std::shared_lock<std::shared_mutex> lock(hookMutex);
    auto found = hookMap.find(hook);
    if (found == hookMap.end()) return false;
    auto has = [&](uint32 id)
    {
